## Code Example

```c
struct vm_budget {
    atomic_long budget_bytes;
    atomic_long tokens;
    int numa_node;
};

void refill(struct vm_budget *vb) {
    atomic_fetch_add(&vb->tokens, REFILL_TOKEN);
}

static bool try_consume(struct vm_budget *vb, long cost) {
    long old, new;
    do {
        old = atomic_load(&vb->tokens);
        if (old < cost)
            return false;
        new = old - cost;
    } while (!atomic_compare_exchange_weak(&vb->tokens, &old, new));
    return true;
}

void submit_io(struct vm_budget *vb, struct bio *bio) {
    if (!try_consume(vb, bio->size))
        enqueue_throttled(vb->numa_node, bio);
    else
        dispatch_io(bio);
}
```

